use serde::{Serialize, Deserialize};

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TopLevel {
    pub color: Color,

    pub either: Option<Name>,

    pub maybe: Option<i64>,

    pub shade: Option<Shade>,

    pub value: Value,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum Color {
    #[serde(rename = "red")]
    Red,

    Green,

    #[serde(rename = "blue-ish")]
    BlueIsh,

    #[serde(rename = "RED")]
    ColorRed,

    #[serde(rename = "TopLevel")]
    TopLevel,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(untagged)]
pub enum Name {
    Bool(bool),

    PurpleString(String),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Shade {
    Red,

    Dark,
}

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(untagged)]
pub enum Value {
    DoubleArray(Vec<f64>),

    Integer(i64),

    PurpleString(String),

    Thing(Thing),
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Thing {
    pub name: Option<Name>,
}
